# Rule check: each odd(≠bg) pixel creates a zigzag arm downward: even rows keep the pixel;
# odd rows below get it at column ±1, alternating, extending to grid bottom.
import json
def f(g):
    H,W=len(g),len(g[0]); bg=g[0][0]
    out=[row[:] for row in g]
    for r0,c0,v in [(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]:
        for r in range(r0+1,H):
            if (r-r0)%2==0:
                out[r][c0]=v
            else:
                out[r][c0-1]=out[r][c0+1]=v
    return out
