def f(g):
    H=len(g);W=len(g[0]);bg=g[0][0];res=[[bg]*W for _ in range(H)]
    for r0 in range(H):
        for c0 in range(W):
            v=g[r0][c0]
            if v==bg: continue
            # nearest edge, prefer vertical edges if tied? choose min over 4 dirs
            ds={'T':r0,'B':H-1-r0,'L':c0,'R':W-1-c0}
            m=min(ds, key=lambda k:ds[k])
            base=(r0+c0)%2
            if m in ('L','R'):
                # horizontal stripe: rows r0-1..r0+1, all cols, (r+c)%2==base
                for r in range(max(0,r0-1),min(H,r0+2)):
                    for c in range(W):
                        if (r+c)%2==base: res[r][c]=v
            else:
                for c in range(max(0,c0-1),min(W,c0+2)):
                    for r in range(H):
                        if (r+c)%2==base: res[r][c]=v
    return res
